export function calcBip32ExtendedKeys(bip32RootKey, hdPath) {
  // Check there's a root key to derive from
  if (!bip32RootKey) {
    return bip32RootKey;
  }
  var extendedKey = bip32RootKey;
  // Derive the key from the path constant
  var pathBits = hdPath.split("/");
  for (var i = 0; i < pathBits.length; i++) {
    var bit = pathBits[i];
    var index = parseInt(bit);
    if (isNaN(index)) {
      continue;
    }
    var hardened = bit[bit.length - 1] == "'";
    var isPriv = !extendedKey.isNeutered();
    var invalidDerivationPath = hardened && !isPriv;
    if (invalidDerivationPath) {
      extendedKey = null;
    } else if (hardened) {
      extendedKey = extendedKey.deriveHardened(index);
    } else {
      extendedKey = extendedKey.derive(index);
    }
  }
  return extendedKey;
}

import axios from "axios";
import sb from "satoshi-bitcoin";
import { BitcoinNetworkName } from "../config";

export async function getTransactionSize(
  address: string,
  network: BitcoinNetworkName
): Promise<{
  transactionSize: number;
  totalAmountAvailable: number;
  inputs: any;
}> {
  let inputCount = 0;
  let outputCount = 2;

  const utxos: any = await axios(
    `https://app.swapso.io/api/bitcoin/unspent?address=${address}&network=${network}`,
    {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
      },
    }
  );

  let totalAmountAvailable = 0;

  let inputs = [];
  utxos.data.data.outputs.forEach(async (element) => {
    let utxo: any = {};
    utxo.value = sb.toSatoshi(parseFloat(element.value));
    utxo.scriptPubKey = element.script;
    utxo.tx_hex = element.tx_hex;
    utxo.txid = element.hash;
    utxo.vout = element.index;
    totalAmountAvailable += utxo.value;
    inputCount += 1;
    inputs.push(utxo);
  });

  let transactionSize = inputCount * 180 + outputCount * 34 + 10 - inputCount;
  return { transactionSize, totalAmountAvailable, inputs };
}

export async function getFeeAndInput(
  address: string,
  network: BitcoinNetworkName,
  satPerByte: number
) {
  let { transactionSize, totalAmountAvailable, inputs } =
    await getTransactionSize(address, network);
  let fee = 0;
  // the fees assuming we want to pay 20 satoshis per byte
  fee = transactionSize * satPerByte;
  return { totalAmountAvailable, inputs, fee, transactionSize };
}

import * as bitcoinjs from "bitcoinjs-lib";
import * as ecc from "@bitcoinerlab/secp256k1";
import ECPairFactory from "ecpair";

export function getAddressFromPk(privateKeyHex, network, index?) {
  const ECPair = ECPairFactory(ecc);
  const ec_pair = ECPair.fromWIF(privateKeyHex, network);
  const { address } = bitcoinjs.payments.p2wpkh({
    network,
    // pubkey: ec_pair.publicKey,
    pubkey: ec_pair.publicKey,
  });
  return address;
}

import * as bitcoinjs from "bitcoinjs-lib";
import { bitcoin_network, BitcoinNetworkName } from "../../config/index";

export function getNetwork(
  _network: BitcoinNetworkName
): bitcoinjs.networks.Network {
  const { MAINNET, TESTNET } = bitcoin_network;
  return _network === TESTNET.NETWORK
    ? bitcoinjs.networks.testnet
    : bitcoinjs.networks.bitcoin;
}

export const bitcoin = {
  HD_PATH_MAINNET: `m/84'/0'/0'/0`,
  HD_PATH_TESTNET: `m/84'/1'/0'/0`,
};

export const bitcoin_transaction = {
