import ObservableStore from "obs-store";

import * as bitcoinjs from "bitcoinjs-lib";
import BIP32Factory from "bip32";
import * as ecc from "@bitcoinerlab/secp256k1";
import ECPairFactory, { ECPairInterface } from "ecpair";

import bitcoinMessage from "bitcoinjs-message";
import * as bip39 from "bip39";
import { randomBytes } from "crypto";
import axios from "axios";
import * as helpers from "./helper/index";

import { bitcoin, bitcoin_network, BitcoinNetworkName } from "./config/index";

// Export TransactionVisualizer
export { TransactionVisualizer } from "./helper/transactionVisualizer";

const { HD_PATH_MAINNET, HD_PATH_TESTNET } = bitcoin;

const { MAINNET, TESTNET } = bitcoin_network;

export class KeyringController {
  bip32: any;
  ECPair: any;
  store: any;
  importedWallets: any;

  constructor(opts: any) {
    this.bip32 = BIP32Factory(ecc);
    this.ECPair = ECPairFactory(ecc);
    this.store = new ObservableStore({
      mnemonic: opts.mnemonic,
      hdPath: opts.network === TESTNET.NETWORK ? HD_PATH_TESTNET : HD_PATH_MAINNET,
      network: helpers.utils.getNetwork(opts.network),
      networkType: opts.network ? opts.network : MAINNET.NETWORK,
      wallet: null,
      address: [],
    });
    this.generateWallet();
    this.importedWallets = [];
  }

  private derivedChild(bip32RootKey: any, hdPath: any, index: number) {
    const path = `${hdPath}/${index}`;
    return bip32RootKey.derivePath(path);
  }

  private toHexString(byteArray: any) {
    return Array.prototype.map
      .call(byteArray, (byte) => ("0" + (byte & 0xff).toString(16)).slice(-2))
      .join("");
  }

  private toByteArray(hexString: string) {
    const result = [];
    for (let i = 0; i < hexString.length; i += 2) {
      result.push(parseInt(hexString.substr(i, 2), 16));
    }
    return result;
  }

  generateWallet() {
    const { mnemonic, network, hdPath } = this.store.getState();
    const seed = bip39.mnemonicToSeedSync(mnemonic);
    const bip32RootKey = this.bip32.fromSeed(seed, network);
    this.updatePersistentStore({ wallet: bip32RootKey });
    return bip32RootKey;
  }

  async addAccount() {
    const { wallet, network, address, hdPath } = this.store.getState();
    const child = this.derivedChild(wallet, hdPath, address.length);

    const { address: _address } = bitcoinjs.payments.p2wpkh({
      pubkey: Buffer.from(child.publicKey),
      network,
    });

    this.persistAllAddress(_address);
    return { address: _address };
  }

  async getAccounts() {
    const { address } = this.store.getState();
    return address;
  }

  async exportPrivateKey(_address: string) {
    const { wallet, network, address, hdPath } = this.store.getState();
    const idx = address.indexOf(_address);
    if (idx < 0) throw "Invalid address, the address is not available in the wallet";

    const child = this.derivedChild(wallet, hdPath, idx);
    const keyPair = this.ECPair.fromWIF(child.toWIF(), network);
    return { privateKey: this.toHexString(keyPair.privateKey) };
  }

  async importWallet(_privateKey: string) {
    try {
      const { network } = this.store.getState();
      const address = helpers.utils.getAddressFromPk(_privateKey, network);
      this.importedWallets.push(address);
      return address;
    } catch (e) {
      return Promise.reject(e);
    }
  }

  async fetchFreshUtxos(address: string, networkType: string) {
    const baseUrl =
      networkType === "MAINNET"
        ? "https://blockstream.info/api"
        : "https://blockstream.info/testnet/api";

    const response = await fetch(`${baseUrl}/address/${address}/utxo`);
    if (!response.ok) {
      throw new Error(`Failed to fetch UTXOs: ${response.statusText}`);
    }

    const utxos = await response.json();

    const detailedUtxos = await Promise.all(
      utxos.map(async (utxo) => {
        const txResponse = await fetch(`${baseUrl}/tx/${utxo.txid}`);
        const txData = await txResponse.json();
        const vout = txData.vout[utxo.vout];
        return {
          txid: utxo.txid,
          vout: utxo.vout,
          value: utxo.value,
          scriptPubKey: vout.scriptpubkey,
        };
      })
    );

    return detailedUtxos;
  }

  async signTransaction(transaction) {
    const { wallet, network, address, networkType, hdPath } = this.store.getState();
    const { from, to, amount, satPerByte: sat } = transaction;
    let satPerByte = sat;

    if (!satPerByte) {
      const data = await this.getFees(transaction);
      satPerByte = data.fees.fast.satPerByte;
    }

    const idx = address.indexOf(from);
    if (idx < 0) throw "Invalid address, the address is not available in the wallet";

    const child: ECPairInterface = this.derivedChild(wallet, hdPath, idx);
    const keyPair: ECPairInterface = this.ECPair.fromWIF(child.toWIF(), network);
    const privateKey = keyPair.privateKey;
    const freshUtxos = await this.fetchFreshUtxos(from, networkType);

    try {
      const signedTransaction = await helpers.signTransaction(
        child,
        keyPair,
        privateKey,
        from,
        to,
        amount,
        satPerByte,
        networkType,
        network,
        freshUtxos
      );
      return { signedTransaction };
    } catch (err) {
      throw err;
    }
  }

  async signMessage(message: string, _address: string, privateKey = null) {
    const { wallet, network, address, hdPath } = this.store.getState();

    if (!privateKey) {
      const idx = address.indexOf(_address);
      if (idx < 0) throw "Invalid address, the address is not available in the wallet";

      try {
        const child = this.derivedChild(wallet, hdPath, idx);
        const keyPair = this.ECPair.fromWIF(child.toWIF(), network);
        const signature = bitcoinMessage.sign(
          message,
          Buffer.from(keyPair.privateKey),
          keyPair.compressed,
          { segwitType: "p2wpkh", extraEntropy: randomBytes(32) }
        );
        return { signedMessage: signature.toString("base64") };
      } catch (err) {
        throw err;
      }
    } else {
      const keyPair = this.ECPair.fromPrivateKey(
        new Uint8Array(this.toByteArray(privateKey))
      );
      const signature = bitcoinMessage.sign(
        message,
        Buffer.from(keyPair.privateKey),
        keyPair.compressed,
        { segwitType: "p2wpkh", extraEntropy: randomBytes(32) }
      );
      return { signedMessage: signature.toString("base64") };
    }
  }

  async sendTransaction(TransactionHex: string) {
    const { networkType } = this.store.getState();
    try {
      const response = await fetch(`https://app.swapso.io/api/bitcoin/send-transaction`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          networkType,
          transactionHex: TransactionHex,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || errorData.error || `HTTP ${response.status}`);
      }

      const result = await response.json();
      return {
        transactionDetails: result.hash || result.data,
      };
    } catch (err) {
      console.error("SendTransaction error:", err);
      throw err;
    }
  }

  async getFees(rawTransaction) {
    const { networkType } = this.store.getState();
    const { from } = rawTransaction;

    try {
      const response = await axios(`https://app.swapso.io/api/bitcoin/network-info?network=${networkType}`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });

      const blocks = response.data.data["mempool"].blocks.slice(0, 3);

      const fees = {
        slow: { satPerByte: parseInt(blocks[2].median_fee_rate) },
        standard: { satPerByte: parseInt(blocks[1].median_fee_rate) },
        fast: { satPerByte: parseInt(blocks[0].median_fee_rate) },
      };

      const { transactionSize } = await helpers.getTransactionSize(from, networkType);

      return {
        transactionSize,
        fees,
      };
    } catch (err) {
      throw err;
    }
  }

  persistAllAddress(_address: string) {
    const { address } = this.store.getState();
    const newAdd = [...address, _address];
    this.store.updateState({ address: newAdd });
    return true;
  }

  updatePersistentStore(obj: object) {
    this.store.updateState(obj);
    return true;
  }
}

export const getBalance = async (
  address: string,
  networkType: BitcoinNetworkName
) => {
  try {
    const balance = await axios(
      `https://app.swapso.io/api/bitcoin/balance?address=${address}&network=${networkType}`,
      {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      }
    );
    return { balance: balance.data.data.confirmed };
  } catch (err) {
    throw err;
  }
};

import { signTransaction } from "./signTransaction";
import { getFeeAndInput, getTransactionSize } from "./calculateFeeAndInput";
import { TransactionVisualizer } from "./transactionVisualizer";
import * as utils from "./utils/index";

export { signTransaction, utils, getFeeAndInput, getTransactionSize, TransactionVisualizer };

import * as bitcoin from "bitcoinjs-lib";
import { ECPairInterface } from "ecpair";
import { BitcoinNetworkName } from "../config";
import BitcoinTransactionSizeCalculator from "./utils/transactionSizeCalculator";

export async function signTransaction(
  child: ECPairInterface,
  keyPair: ECPairInterface,
  privateKey: any,
  from: string,
  to: string,
  amountToSend: number,
  satPerByte = 1,
  networkType: BitcoinNetworkName,
  network: bitcoin.networks.Network,
  freshUtxos: any[] = []
) {
  const psbt = new bitcoin.Psbt({ network });

  const {
    feeInSats,
    selectedUTXOs,
    changeAmount,
  } = await BitcoinTransactionSizeCalculator.calculateOptimalFee(from, amountToSend, satPerByte, freshUtxos);

  const totalAmountAvailable = selectedUTXOs.reduce((sum, utxo) => sum + utxo.value, 0);
    // console.log("totalAmountAvailable:", totalAmountAvailable);
    // console.log("amountToSend:", amountToSend);
    // console.log("fee:", feeInSats);

  if (totalAmountAvailable < amountToSend + feeInSats) {
    throw new Error("Balance is too low for this transaction");
  }

  psbt.addOutput({ address: to, value: amountToSend });

  if (changeAmount >= 100) {
    psbt.addOutput({ address: from, value: changeAmount });
  }

  selectedUTXOs.forEach((unspentOutput: any) => {
    psbt.addInput({
      hash: unspentOutput.txid,
      index: unspentOutput.vout,
      witnessUtxo: {
        script: Buffer.from(unspentOutput.scriptPubKey, "hex"),
        value: unspentOutput.value,
      },
    });
  });

  const buffer = Buffer.from(keyPair.publicKey);

  const mySigner: any = {
    publicKey: buffer,
    sign: (hash: any) => {
      const signature = Buffer.from(keyPair.sign(hash));
      return signature;
    },
  };

  selectedUTXOs.forEach((_, key: number) => {
    psbt.signInput(key, mySigner);
  });

  psbt.finalizeAllInputs();

  const transaction = psbt.extractTransaction();
  return transaction.toHex();
}

interface UTXO {
  txid: string;
  vout: number;
  value: number;
  confirmations: number;
  scriptPubKey?: {
    type: string;
    addresses?: string[];
  };
}

interface TransactionSizeEstimate {
  size: number;
  weight: number;
  vBytes: number;
  inputCount: number;
  outputCount: number;
  inputTypes: string[];
}

class BitcoinTransactionSizeCalculator {
  
  static getAddressType(address: string): string {
    if (address.startsWith('bc1q') && address.length === 42) return 'P2WPKH';
    if (address.startsWith('bc1p') && address.length === 62) return 'P2TR';
    if (address.startsWith('3')) return 'P2SH';
    if (address.startsWith('1')) return 'P2PKH';
    if (address.startsWith('bc1') && address.length > 42) return 'P2WSH';
    return 'UNKNOWN';
  }

  // Input size calculations (in weight units)
  static getInputWeight(addressType: string): number {
    const weights = {
      'P2PKH': 592,      // Legacy: 148 * 4
      'P2SH': 640,       // Script hash: 160 * 4  
      'P2WPKH': 272,     // Native segwit: 68 * 4
      'P2WSH': 272,      // Native segwit script: 68 * 4
      'P2TR': 230,       // Taproot: 57.5 * 4
      'UNKNOWN': 592     // Conservative fallback
    };
    return weights[addressType] || weights['UNKNOWN'];
  }

  // Output size calculations (in weight units)
  static getOutputWeight(addressType: string): number {
    const weights = {
      'P2PKH': 136,      // Legacy: 34 * 4
      'P2SH': 128,       // Script hash: 32 * 4
      'P2WPKH': 124,     // Native segwit: 31 * 4
      'P2WSH': 172,      // Native segwit script: 43 * 4
      'P2TR': 172,       // Taproot: 43 * 4
      'UNKNOWN': 136     // Conservative fallback
    };
    return weights[addressType] || weights['UNKNOWN'];
  }

  // Main transaction size estimation function
  static estimateTransactionSize(
    utxos: UTXO[], 
    outputCount: number = 2,
    senderAddress?: string
  ): TransactionSizeEstimate {
    
    if (!utxos || utxos.length === 0) {
      // Fallback estimation
      return {
        size: 140,
        weight: 560,
        vBytes: 140,
        inputCount: 1,
        outputCount: 2,
        inputTypes: ['P2WPKH']
      };
    }

    const inputCount = utxos.length;
    let totalWeight = 0;
    const inputTypes: string[] = [];

    // Transaction overhead (version + locktime + input/output counts)
    totalWeight += 40; // 10 bytes * 4

    // Calculate input weights
    for (const utxo of utxos) {
      let addressType = 'P2WPKH'; // Default assumption
      
      // Trying to determine address type from scriptPubKey or addresses
      if (utxo.scriptPubKey?.addresses?.[0]) {
        addressType = this.getAddressType(utxo.scriptPubKey.addresses[0]);
      } else if (senderAddress) {
        addressType = this.getAddressType(senderAddress);
      }
      
      inputTypes.push(addressType);
      totalWeight += this.getInputWeight(addressType);
    }

    // Calculate output weights (assume recipient gets same type as sender)
    const outputType = senderAddress ? this.getAddressType(senderAddress) : 'P2WPKH';
    totalWeight += outputCount * this.getOutputWeight(outputType);

    // Convert weight to virtual bytes (rounded up)
    const vBytes = Math.ceil(totalWeight / 4);
    const size = Math.ceil(totalWeight / 4); // Approximate size

    return {
      size,
      weight: totalWeight,
      vBytes,
      inputCount,
      outputCount,
      inputTypes
    };
  }

  // FIXED: More robust UTXO selection with consistent fee calculation
  static selectOptimalUTXOs(utxos: UTXO[], targetAmount: number, feeRate: number, senderAddress?: string): {
    selectedUTXOs: UTXO[];
    totalInput: number;
    estimatedFee: number;
    changeAmount: number;
    finalOutputCount: number;
  } {
    if (!utxos || utxos.length === 0) {
      throw new Error('No UTXOs available - wallet may be empty or all funds already spent');
    }

    const sortedUTXOs = [...utxos].sort((a, b) => b.value - a.value);
    
    let selectedUTXOs: UTXO[] = [];
    let totalInput = 0;

    for (const utxo of sortedUTXOs) {
      selectedUTXOs.push(utxo);
      totalInput += utxo.value;

      // CRITICAL FIX: Calculate fee for both scenarios (with and without change)
      
      // Scenario 1: With change output (2 outputs)
      const estimateWithChange = this.estimateTransactionSize(selectedUTXOs, 2, senderAddress);
      const feeWithChange = Math.ceil(estimateWithChange.vBytes * feeRate);
      const changeWithChange = totalInput - targetAmount - feeWithChange;
      
      // Scenario 2: Without change output (1 output) - if change would be dust
      const estimateWithoutChange = this.estimateTransactionSize(selectedUTXOs, 1, senderAddress);
      const feeWithoutChange = Math.ceil(estimateWithoutChange.vBytes * feeRate);
      const changeWithoutChange = totalInput - targetAmount - feeWithoutChange;

      // Decide which scenario to use
      let finalFee: number;
      let finalChange: number;
      let finalOutputCount: number;

      if (changeWithChange >= 546) { // Bitcoin dust threshold is 546 sats, not 100
        // Use change output scenario
        finalFee = feeWithChange;
        finalChange = changeWithChange;
        finalOutputCount = 2;
      } else {
        // Use no-change scenario (dust becomes extra fee)
        finalFee = feeWithoutChange;
        finalChange = 0;
        finalOutputCount = 1;
      }

      console.log(`💰 UTXO Selection Debug:
        - Selected UTXOs: ${selectedUTXOs.length}
        - Total input: ${totalInput} sats
        - Target amount: ${targetAmount} sats
        - Fee (${finalOutputCount} outputs): ${finalFee} sats
        - Change: ${finalChange} sats
        - vBytes: ${finalOutputCount === 2 ? estimateWithChange.vBytes : estimateWithoutChange.vBytes}
        - Fee rate: ${feeRate} sat/vB`);

      // Check if we have enough funds
      if (totalInput >= targetAmount + finalFee) {
        return {
          selectedUTXOs,
          totalInput,
          estimatedFee: finalFee,
          changeAmount: finalChange,
          finalOutputCount
        };
      }
    }

    // Calculate what we actually need vs what we have
    const estimateForAll = this.estimateTransactionSize(selectedUTXOs, 1, senderAddress);
    const minFeeNeeded = Math.ceil(estimateForAll.vBytes * feeRate);
    const totalNeeded = targetAmount + minFeeNeeded;

    throw new Error(`Insufficient funds. Need ${totalNeeded} sats (${targetAmount} + ${minFeeNeeded} fee), have ${totalInput} sats`);
  }

  // FIXED: Simplified and more consistent fee calculation
  static async calculateOptimalFee(
    senderAddress: string,
    targetAmount: number,
    feeRate: number,
    utxos?: UTXO[]
  ): Promise<{
    fee: number;
    feeInSats: number;
    transactionSize: number;
    selectedUTXOs: UTXO[];
    changeAmount: number;
  }> {
    if (!utxos) {
      throw new Error('UTXOs required for accurate fee calculation');
    }

    if (utxos.length === 0) {
      const estimatedSize = this.estimateTransactionSize([], 2, senderAddress);
      const estimatedFeeInSats = Math.ceil(estimatedSize.vBytes * feeRate);
      return {
        fee: estimatedFeeInSats / 1e8,
        feeInSats: estimatedFeeInSats,
        transactionSize: estimatedSize.vBytes,
        selectedUTXOs: [],
        changeAmount: 0
      };
    }

    try {
      const selection = this.selectOptimalUTXOs(utxos, targetAmount, feeRate, senderAddress);
      
      // CRITICAL: Use the SAME calculation logic as selectOptimalUTXOs
      const finalSize = this.estimateTransactionSize(
        selection.selectedUTXOs,
        selection.finalOutputCount,
        senderAddress
      );

      // CRITICAL: Use Math.ceil to ensure we never underpay
      const finalFeeInSats = Math.ceil(finalSize.vBytes * feeRate);
      
      // Add small buffer to prevent edge cases (optional but recommended)
      const bufferedFeeInSats = finalFeeInSats + 1; // Add 1 sat buffer
      
      console.log(`🔥 Final Fee Calculation:
        - Transaction size: ${finalSize.vBytes} vBytes
        - Fee rate: ${feeRate} sat/vB
        - Calculated fee: ${finalFeeInSats} sats
        - Buffered fee: ${bufferedFeeInSats} sats
        - Output count: ${selection.finalOutputCount}`);

      return {
        fee: bufferedFeeInSats / 1e8,
        feeInSats: bufferedFeeInSats,
        transactionSize: finalSize.vBytes,
        selectedUTXOs: selection.selectedUTXOs,
        changeAmount: selection.changeAmount
      };
    } catch (error) {
      console.error('Fee calculation error:', error);
      throw error;
    }
  }

  static convertAmount(amount: number, fromUnit: string, toUnit: string): number {
    const btcAmount = fromUnit === 'sats' ? amount / 1e8 : amount;
    return toUnit === 'sats' ? btcAmount * 1e8 : btcAmount;
  }

  static formatFeeDisplay(feeInSats: number, feeRate: number, vBytes: number): string {
    const feeInBTC = (feeInSats / 1e8).toFixed(8);
    return `${feeInSats} sats (${feeInBTC} BTC) • ${feeRate} sat/vB • ${vBytes} vBytes`;
  }
}

export default BitcoinTransactionSizeCalculator;

import axios from 'axios';

interface TxInput {
  txid: string;
  vout: number;
  prevout: {
    scriptpubkey: string;
    scriptpubkey_asm: string;
    scriptpubkey_type: string;
    scriptpubkey_address: string;
    value: number;
  };
  scriptsig: string;
  scriptsig_asm: string;
  witness: string[];
  is_coinbase: boolean;
  sequence: number;
}

interface TxOutput {
  scriptpubkey: string;
  scriptpubkey_asm: string;
  scriptpubkey_type: string;
  scriptpubkey_address: string;
  value: number;
}

interface Transaction {
  txid: string;
  version: number;
  locktime: number;
  vin: TxInput[];
  vout: TxOutput[];
  size: number;
  weight: number;
  fee: number;
  status: {
    confirmed: boolean;
    block_height?: number;
    block_hash?: string;
    block_time?: number;
  };
}

export interface VisualizationNode {
  id: string;
  label: string;
  group: 'transaction' | 'address' | 'input' | 'output';
  details?: any; // Additional info for tooltip
}

export interface VisualizationEdge {
  from: string;
  to: string;
  label?: string; // Value or index
  value?: number; // Visual weight
  arrows?: string;
  color?: {
    color: string;
  };
}

export interface VisualizationData {
  nodes: VisualizationNode[];
  edges: VisualizationEdge[];
  summary: {
    txid: string;
    fee: number;
    size: number;
    weight: number;
    confirmed: boolean;
    time?: string;
    totalInput: number;
    totalOutput: number;
  };
}

export class TransactionVisualizer {
  private apiBaseUrl: string;

  constructor(network: 'MAINNET' | 'TESTNET' = 'MAINNET') {
    this.apiBaseUrl = network === 'TESTNET' 
      ? 'https://mempool.space/testnet/api' 
      : 'https://mempool.space/api';
  }

  /**
   * Fetches transaction data and constructs a visualization graph.
   * @param txId The transaction ID (hash) to analyze.
   * @returns VisualizationData object compatible with Vis.js
   */
  async analyzeTransaction(txId: string): Promise<VisualizationData> {
    try {
      const response = await axios.get<Transaction>(`${this.apiBaseUrl}/tx/${txId}`);
      const tx = response.data;
      
      const nodes: VisualizationNode[] = [];
      const edges: VisualizationEdge[] = [];
      
      // Central Node: The Transaction itself
      nodes.push({
        id: tx.txid,
        label: `TX\n${tx.txid.substring(0, 8)}...`,
        group: 'transaction',
        details: {
          fullHash: tx.txid,
          fee: tx.fee,
          size: tx.size,
          weight: tx.weight,
          confirmed: tx.status.confirmed,
          blockTime: tx.status.block_time ? new Date(tx.status.block_time * 1000).toLocaleString() : 'Pending'
        }
      });

      let totalInput = 0;
      let totalOutput = 0;

      // Process Inputs (VIN)
      tx.vin.forEach((input, index) => {
        const inputId = `in-${index}-${tx.txid}`;
        
        let label = `Input #${index}`;
        let subLabel = '';
        let address = 'Unknown';
        let amount = 0;

        if (input.is_coinbase) {
          label = 'Coinbase';
          subLabel = '(New Coins)';
        } else if (input.prevout) {
          address = input.prevout.scriptpubkey_address || 'Unknown Address';
          amount = input.prevout.value;
          subLabel = `${(amount / 100000000).toFixed(8)} BTC`;
          label = `${address.substring(0, 8)}...`;
          totalInput += amount;

          // Add address node if not traced back (for simplicity, treating input source as address node)
          // Ideally we trace back to previous TX, but visualization gets messy.
          // Let's create a node for the Sender Address
          const addressNodeId = `addr-${address}`;
          if (!nodes.find(n => n.id === addressNodeId)) {
             nodes.push({
               id: addressNodeId,
               label: `${address.substring(0, 8)}...`,
               group: 'address',
               details: { address: address }
             });
          }
          
          // Edge from Address to Transaction
          edges.push({
            from: addressNodeId,
            to: tx.txid,
            label: `${(amount / 100000000).toFixed(8)} BTC`,
            value: amount,
            arrows: 'to',
            color: { color: '#ffaaaa' } // Inlet color
          });
        }
      });

      // Process Outputs (VOUT)
      tx.vout.forEach((output, index) => {
        const address = output.scriptpubkey_address || 'OP_RETURN / Unparsed';
        const amount = output.value;
        totalOutput += amount;
        
        const addressNodeId = `addr-out-${address}-${index}`; // Unique output node per index to handle change addresses clearly or same address used multiple times? 
        // Actually, if same address receives multiple outputs, we might merge, but usually distinct vouts.
        // Let's use address as ID if we want to merge, but `index` makes it distinct output. 
        // Visualization often cleaner if we merge same addresses.
        
        const existingNode = nodes.find(n => n.id === `addr-${address}`);
        let targetId = existingNode ? existingNode.id : `addr-${address}`;

        if (!existingNode) {
          nodes.push({
             id: targetId,
             label: `${address.substring(0, 6)}...`,
             group: 'address',
             details: { address: address }
          });
        }

        edges.push({
          from: tx.txid,
          to: targetId,
          label: `${(amount / 100000000).toFixed(8)} BTC`,
          value: amount,
          arrows: 'to',
          color: { color: '#aaffaa' } // Outlet color
        });
      });

      return {
        nodes,
        edges,
        summary: {
          txid: tx.txid,
          fee: tx.fee,
          size: tx.size,
          weight: tx.weight,
          confirmed: tx.status.confirmed,
          time: tx.status.block_time ? new Date(tx.status.block_time * 1000).toLocaleString() : 'Pending',
          totalInput,
          totalOutput
        }
      };

    } catch (error: any) {
      console.error("Error analyzing transaction:", error);
      throw new Error(`Failed to analyze transaction: ${error.message}`);
    }
  }
}

